#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill. Stafeed Cloudflare setup (ticket #34).
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Names the CI deploy workflow (#42) reads. Keep in sync with it.
REPO="danieljreije/stafeed"
PROJECT_NAME="stafeed"
SECRET_TOKEN="CLOUDFLARE_API_TOKEN"
SECRET_ACCOUNT="CLOUDFLARE_ACCOUNT_ID"
VAR_PROJECT="CLOUDFLARE_PROJECT_NAME"

export GH_REPO="$REPO"   # every gh call below targets Stafeed, whatever folder you run from
# gh is often missing from PATH in a fresh Windows shell; look in its usual home.
if ! command -v gh >/dev/null 2>&1; then
  for d in "/c/Program Files/GitHub CLI" "/mnt/c/Program Files/GitHub CLI"; do
    [[ -x "$d/gh.exe" ]] && PATH="$PATH:$d" && break
  done
fi

# cf_api METHOD PATH [JSON_BODY]: calls the Cloudflare API with $CF_TOKEN.
# The token goes to curl on stdin, so it never shows in the process list or on
# screen. Prints the response body; the caller only checks "success".
cf_api() {
  local method="$1" path="$2" body="${3:-}"
  local args=(-sS -X "$method" -K - "https://api.cloudflare.com/client/v4$path")
  [[ -n "$body" ]] && args+=(-H "Content-Type: application/json" --data "$body")
  printf 'header = "Authorization: Bearer %s"\n' "$CF_TOKEN" | curl "${args[@]}" 2>/dev/null || true
}
cf_ok() { grep -q '"success": *true' <<<"$1"; }

# ── Pre-flight: gh must work, and re-runs must not clobber good setup ─────
if ! command -v gh >/dev/null 2>&1 || ! gh auth status >/dev/null 2>&1; then
  printf '\n  gh (GitHub CLI) is missing or not logged in. Run "gh auth login" first, then re-run this script.\n\n'
  exit 1
fi
EXISTING=$(gh secret list 2>/dev/null || true)
if grep -q "^$SECRET_TOKEN" <<<"$EXISTING" && grep -q "^$SECRET_ACCOUNT" <<<"$EXISTING"; then
  printf '\n  Both GitHub secrets (%s, %s) are already stored for %s.\n' "$SECRET_TOKEN" "$SECRET_ACCOUNT" "$REPO"
  confirm "Replace them with new values?" || { printf '\n  Nothing changed. You are already set up.\n\n'; exit 0; }
fi

TOTAL_STAGES=5
banner "Stafeed: Cloudflare setup (free live links for the app)"

stage "Cloudflare account"
say "Cloudflare hosts the web version of Stafeed so you can open it on your phone."
say "It is free. Stafeed never pays Cloudflare and Cloudflare never touches shoppers' money."
open_url "https://dash.cloudflare.com/sign-up"
step "Sign up with your email and a password (skip if you already have an account)."
step "Verify your email if Cloudflare asks, then log in to the dashboard."
step "If it offers to add a website or domain, you can skip that. You don't need one."
pause "Logged in to the Cloudflare dashboard? Press Enter."

stage "Your Cloudflare account ID"
say "The account ID is a 32-character code that says which account to deploy into."
say "It is not secret, but CI needs it."
open_url "https://dash.cloudflare.com/"
step "Look at the address bar: after dash.cloudflare.com/ comes a long code. That is it."
note "Or: Workers & Pages in the left menu, then 'Account ID' on the right."
while :; do
  ask CLOUDFLARE_ACCOUNT_ID "Paste the account ID:"
  CLOUDFLARE_ACCOUNT_ID="${CLOUDFLARE_ACCOUNT_ID//[[:space:]]/}"
  [[ "$CLOUDFLARE_ACCOUNT_ID" =~ ^[0-9a-fA-F]{32}$ ]] && break
  warn "That should be 32 letters and digits (0-9, a-f). Try again."
done

stage "API token (the key CI uses to publish)"
say "A token lets GitHub publish to Cloudflare for you, and nothing else."
open_url "https://dash.cloudflare.com/profile/api-tokens"
step "Click 'Create Token', then 'Create Custom Token' ('Get started')."
step "Token name: Stafeed deploy"
step "Permissions: choose Account, then Cloudflare Pages, then Edit."
step "Account Resources: Include, then your account."
step "Click 'Continue to summary', then 'Create Token'."
step "Copy the token. Cloudflare shows it only once."
warn "Your typing is hidden on purpose. Paste, then press Enter."
while :; do
  ask_secret CF_TOKEN "Paste the token:"
  CF_TOKEN="${CF_TOKEN//[[:space:]]/}"
  [[ -n "$CF_TOKEN" ]] && break
  warn "Nothing pasted. Try again."
done

stage "Pages project for Stafeed"
say "Checking the token works and that the project '$PROJECT_NAME' exists..."
RESP=$(cf_api GET "/accounts/$CLOUDFLARE_ACCOUNT_ID/pages/projects/$PROJECT_NAME")
if cf_ok "$RESP"; then
  say "✓ Project '$PROJECT_NAME' already exists. Reusing it."
else
  RESP=$(cf_api GET "/accounts/$CLOUDFLARE_ACCOUNT_ID/pages/projects")
  if ! cf_ok "$RESP"; then
    warn "Cloudflare rejected the token or account ID."
    say "Check: the account ID is right, and the token has 'Account > Cloudflare Pages > Edit'."
    say "Re-run this script to try again. Nothing was stored."
    exit 1
  fi
  say "Token works. The project doesn't exist yet."
  if confirm "Create the free Pages project '$PROJECT_NAME' now?"; then
    RESP=$(cf_api POST "/accounts/$CLOUDFLARE_ACCOUNT_ID/pages/projects" \
      "{\"name\":\"$PROJECT_NAME\",\"production_branch\":\"main\"}")
    if cf_ok "$RESP"; then
      say "✓ Created project '$PROJECT_NAME'."
    else
      warn "Cloudflare could not create the project (the name may be taken in your account)."
      say "Re-run this script to try again. Nothing was stored."
      exit 1
    fi
  else
    say "Stopped before creating anything. Re-run when ready. Nothing was stored."
    exit 0
  fi
fi

stage "Store the secrets in GitHub"
say "Saving to GitHub repository $REPO. Values are sent straight to GitHub"
say "and are never saved in the repo or shown again."
set_secret "$SECRET_TOKEN" "$CF_TOKEN"
set_secret "$SECRET_ACCOUNT" "$CLOUDFLARE_ACCOUNT_ID"
set_var "$VAR_PROJECT" "$PROJECT_NAME"
unset CF_TOKEN
pause "Press Enter to finish."

finish
say "Next: comment \"done\" on ticket #40."
